begin;

delete from public.reviews where provider_id in (select id from public.providers where is_demo);
delete from public.provider_services where provider_id in (select id from public.providers where is_demo);
delete from public.providers where is_demo and id not in (select provider_id from public.plans union select provider_id from public.visits);

on conflict (id) do update set name = excluded.name, category = excluded.category, default_cadence = excluded.default_cadence, typical_price = excluded.typical_price, sort_order = excluded.sort_order, is_core = excluded.is_core;

